import java.util.Arrays;
import java.util.Random;

public class QuickSort {

    private static final int INSERTION_SORT_THRESHOLD = 10; // Optimize for small subarrays

    public static <T extends Comparable<T>> void sort(T[] arr) {
        if (arr == null || arr.length < 2) {
            return; // Handle empty or single-element arrays
        }
        sort(arr, 0, arr.length - 1);
    }

    private static <T extends Comparable<T>> void sort(T[] arr, int low, int high) {
        if (high - low < INSERTION_SORT_THRESHOLD) {
            insertionSort(arr, low, high);
            return;
        }
        int pivotIndex = partition(arr, low, high);
        sort(arr, low, pivotIndex - 1);
        sort(arr, pivotIndex + 1, high);
    }

    private static <T extends Comparable<T>> int partition(T[] arr, int low, int high) {
        Random random = new Random();
        int pivotIndex = low + random.nextInt(high - low + 1); // Randomized pivot selection
        T pivot = arr[pivotIndex];
        swap(arr, pivotIndex, high); // Move pivot to the end

        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (arr[j].compareTo(pivot) < 0) {
                i++;
                swap(arr, i, j);
            }
        }
        swap(arr, i + 1, high); // Move pivot to its final sorted position
        return i + 1;
    }

    private static <T extends Comparable<T>> void swap(T[] arr, int i, int j) {
        T temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    // Insertion sort for small subarrays
    private static <T extends Comparable<T>> void insertionSort(T[] arr, int low, int high) {
        for (int i = low + 1; i <= high; i++) {
            T key = arr[i];
            int j = i - 1;
            while (j >= low && arr[j].compareTo(key) > 0) {
                arr[j + 1] = arr[j];
                j--;
            }
            arr[j + 1] = key;
        }
    }


    public static void main(String[] args) {
        Integer[] arr = {12, 11, 13, 5, 6, 7};
        System.out.println("Unsorted array: " + Arrays.toString(arr));
        sort(arr);
        System.out.println("Sorted array: " + Arrays.toString(arr));


        String[] strArr = {"banana", "apple", "orange", "grape"};
        System.out.println("Unsorted string array: " + Arrays.toString(strArr));
        sort(strArr);
        System.out.println("Sorted string array: " + Arrays.toString(strArr));

    }
}
